"""Tests for `gate.py argument-graph` -- replaces the prose check at
src/skills/write/SKILL.md:310-325 ("This is not a subagent call; it is
reasoning directly over the outline JSON already in memory"). Design spec:
docs/audits/2026-09-04-determinism-audit.md, sections 3.1, 5.

Per TST-08, a gate is not trusted until it has been proven able to fail --
every check below has a companion test that plants the specific defect
and asserts the non-zero exit, alongside a baseline fixture proving the
same check does NOT fire on a clean outline.

Node schema: src/agents/architect.md's `id` / `claim` / `evidence` /
`depends_on` / `thesis_link` / `argument_role` fields. Flattening: a
section with no nested `units` array IS itself a node; a section WITH one
contributes only its units (src/workflows/write-sections.js's
`flattenUnits()`), which tests/fixtures/gate/outline-valid.json exercises
directly (section "II" has units "II.1"/"II.2" and is itself not a node).
"""

import json
import os
import subprocess
import sys
import tempfile
import unittest

ROOT_DIR = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
GATE = os.path.join(ROOT_DIR, "src", "scripts", "gate.py")
VALID_OUTLINE_PATH = os.path.join(ROOT_DIR, "tests", "fixtures", "gate", "outline-valid.json")


def run_gate(*args):
    """Invoke gate.py as a real subprocess. Auto-injects a scratch
    --ledger into a throwaway tempdir when the caller didn't supply one:
    without this, gate.py resolves the ledger via $CLAUDE_PROJECT_DIR (or
    cwd) and would write into any REAL .academic-helper/session-state.json
    that happens to exist there -- harmless in this repo's own CI, but not
    something a test should ever risk touching (TST-09 spirit: no
    ambient-environment dependency, including this one).
    """
    if "--ledger" not in args and args:
        with tempfile.TemporaryDirectory() as ledger_dir:
            return subprocess.run(
                [sys.executable, GATE, *args, "--ledger", os.path.join(ledger_dir, "session-state.json")],
                capture_output=True,
                text=True,
                timeout=30,
            )
    return subprocess.run(
        [sys.executable, GATE, *args],
        capture_output=True,
        text=True,
        timeout=30,
    )


def load_valid_outline():
    with open(VALID_OUTLINE_PATH, encoding="utf-8") as fh:
        return json.load(fh)


def run_on_outline(outline):
    with tempfile.TemporaryDirectory() as tmpdir:
        path = os.path.join(tmpdir, "outline.json")
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(outline, fh, ensure_ascii=False)
        return run_gate("argument-graph", path, "--json")


def flat_node(**overrides):
    node = {
        "id": "X",
        "title": "A node",
        "argument_role": "supports thesis",
        "claim": "Some claim",
        "evidence": ["ev1"],
        "depends_on": [],
        "thesis_link": "Advances the thesis.",
    }
    node.update(overrides)
    return node


class TestValidOutlinePasses(unittest.TestCase):
    def test_valid_fixture_passes(self):
        proc = run_gate("argument-graph", VALID_OUTLINE_PATH, "--json")
        self.assertEqual(proc.returncode, 0, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "pass")
        self.assertEqual(payload["violations"], [])

    def test_section_with_units_is_not_itself_a_node(self):
        """Section 'II' in the fixture has no claim/evidence/thesis_link of
        its own (only its units II.1/II.2 do) and must NOT be flagged --
        proving flattening matches write-sections.js's flattenUnits().
        """
        proc = run_gate("argument-graph", VALID_OUTLINE_PATH, "--json")
        payload = json.loads(proc.stdout)
        node_ids = {v.get("nodeId") for v in payload["violations"]}
        self.assertNotIn("II", node_ids)


class TestCycleDetection(unittest.TestCase):
    def test_two_node_cycle_fails(self):
        outline = {
            "sections": [
                flat_node(id="A", depends_on=["B"]),
                flat_node(id="B", depends_on=["A"]),
            ]
        }
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout + proc.stderr)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "fail")
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("cycle", checks)

    def test_self_dependency_is_a_cycle(self):
        outline = {"sections": [flat_node(id="A", depends_on=["A"])]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("cycle", checks)

    def test_acyclic_outline_has_no_cycle_violation(self):
        outline = {
            "sections": [
                flat_node(id="A", depends_on=[]),
                flat_node(id="B", depends_on=["A"]),
                flat_node(id="C", depends_on=["A", "B"]),
            ]
        }
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 0, proc.stdout)

    def test_cycle_is_tagged_cycle_not_ordering(self):
        """A depends_on cycle necessarily also violates positional order in
        at least one direction (one edge of a cycle must point to a later
        position in a strict list) -- but the cycle itself must be
        reported under check='cycle', never mislabeled 'ordering'. The two
        checks must stay distinguishable in the output: a caller can
        always tell 'the outline has a cycle' apart from 'the outline is
        merely listed out of order'.
        """
        outline = {
            "sections": [
                flat_node(id="A", depends_on=["B"]),
                flat_node(id="B", depends_on=["A"]),
            ]
        }
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        cycle_violations = [v for v in payload["violations"] if v["check"] == "cycle"]
        self.assertEqual(len(cycle_violations), 1)
        self.assertEqual(cycle_violations[0]["check"], "cycle")


class TestDanglingDependency(unittest.TestCase):
    def test_depends_on_unknown_id_fails(self):
        outline = {"sections": [flat_node(id="A", depends_on=["ghost"])]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("dangling-dependency", checks)
        dangling = [v for v in payload["violations"] if v["check"] == "dangling-dependency"][0]
        self.assertEqual(dangling["nodeId"], "A")
        self.assertIn("ghost", dangling["detail"])


