class TestOrphanCheck(unittest.TestCase):
    """SKILL.md:317's "No orphan sections/units" check: a node's claim must
    trace back to the thesis via `thesis_link`, either its own or one
    reachable by walking `depends_on` transitively.
    """

    def test_absent_thesis_link_with_none_reachable_fails(self):
        node = flat_node(id="A")
        del node["thesis_link"]
        outline = {"sections": [node]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("orphan", checks)

    def test_empty_string_thesis_link_with_none_reachable_fails(self):
        outline = {"sections": [flat_node(id="A", thesis_link="")]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("orphan", checks)

    def test_whitespace_only_thesis_link_with_none_reachable_fails(self):
        outline = {"sections": [flat_node(id="A", thesis_link="   ")]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)

    def test_chain_that_never_reaches_a_thesis_link_fails(self):
        """A -> B -> C, and none of the three carries a thesis_link
        anywhere in the chain: all three are orphans (plants the exact
        mutation from the acceptance spec: a depends_on chain that never
        reaches a thesis_link)."""
        node_a = flat_node(id="A", depends_on=["B"])
        del node_a["thesis_link"]
        node_b = flat_node(id="B", depends_on=["C"])
        del node_b["thesis_link"]
        node_c = flat_node(id="C", depends_on=[])
        del node_c["thesis_link"]
        outline = {"sections": [node_a, node_b, node_c]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        orphan_ids = {v["nodeId"] for v in payload["violations"] if v["check"] == "orphan"}
        self.assertEqual(orphan_ids, {"A", "B", "C"})

    def test_node_without_own_thesis_link_but_transitively_reaching_one_passes(self):
        """The false-positive guard proving the check was FIXED to walk
        the chain, not just loosened to skip the field: a node with NO
        thesis_link of its own must NOT be flagged as an orphan when it
        depends_on a node that (transitively) has one.
        """
        node_a = flat_node(id="A", depends_on=[], thesis_link="States the thesis.")
        node_b = flat_node(id="B", depends_on=["A"])
        del node_b["thesis_link"]
        outline = {"sections": [node_a, node_b]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 0, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["violations"], [])

    def test_transitive_reach_through_two_hops_passes(self):
        node_a = flat_node(id="A", depends_on=[], thesis_link="States the thesis.")
        node_b = flat_node(id="B", depends_on=["A"])
        del node_b["thesis_link"]
        node_c = flat_node(id="C", depends_on=["B"])
        del node_c["thesis_link"]
        outline = {"sections": [node_a, node_b, node_c]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 0, proc.stdout)

    def test_cycle_with_no_thesis_link_anywhere_is_still_orphaned(self):
        """A -> B -> A, neither carries a thesis_link: the chain walk can
        never resolve through a cycle that itself never reaches one, so
        both nodes are correctly flagged orphan (in addition to cycle).
        """
        node_a = flat_node(id="A", depends_on=["B"])
        del node_a["thesis_link"]
        node_b = flat_node(id="B", depends_on=["A"])
        del node_b["thesis_link"]
        outline = {"sections": [node_a, node_b]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        orphan_ids = {v["nodeId"] for v in payload["violations"] if v["check"] == "orphan"}
        self.assertEqual(orphan_ids, {"A", "B"})


class TestDependencyOrdering(unittest.TestCase):
    """SKILL.md:320's "Dependency ordering" check: the flattened outline
    sequence (the Step 6 writing order) must respect `depends_on` -- a node
    cannot appear before every node listed in its `depends_on`. Positional,
    distinct from cycle detection: a cycle-free graph can still be listed
    in the wrong order.
    """

    def test_dependency_listed_after_the_node_that_needs_it_fails(self):
        """Plant the exact mutation from the acceptance spec: a node at
        position i whose depends_on names a node at position j > i.
        """
        outline = {
            "sections": [
                flat_node(id="A", depends_on=["B"]),  # position 0, needs B
                flat_node(id="B", depends_on=[]),  # position 1 -- too late
            ]
        }
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertIn("ordering", checks)
        violation = [v for v in payload["violations"] if v["check"] == "ordering"][0]
        self.assertEqual(violation["nodeId"], "A")
        self.assertEqual(violation["dependsOn"], "B")
        self.assertEqual(violation["nodePosition"], 0)
        self.assertEqual(violation["dependencyPosition"], 1)

    def test_correctly_ordered_outline_passes(self):
        outline = {
            "sections": [
                flat_node(id="A", depends_on=[]),
                flat_node(id="B", depends_on=["A"]),
                flat_node(id="C", depends_on=["A", "B"]),
            ]
        }
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 0, proc.stdout)

    def test_valid_fixture_is_correctly_ordered(self):
        proc = run_gate("argument-graph", VALID_OUTLINE_PATH, "--json")
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertNotIn("ordering", checks)

    def test_ordering_reaches_into_nested_units_too(self):
        """Ordering must run over the SAME flattened index the
        empty-evidence check already proved reaches into `units` -- a unit
        depending on a unit that appears later in the same section must
        still be caught.
        """
        outline = {
            "sections": [
                flat_node(id="I", depends_on=[]),
                {
                    "id": "II",
                    "units": [
                        flat_node(id="II.1", depends_on=["II.2"]),  # depends on a later unit
                        flat_node(id="II.2", depends_on=["I"]),
                    ],
                },
            ]
        }
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        violation = [v for v in payload["violations"] if v["check"] == "ordering"][0]
        self.assertEqual(violation["nodeId"], "II.1")
        self.assertEqual(violation["dependsOn"], "II.2")

    def test_dangling_dependency_is_not_also_reported_as_ordering(self):
        """A depends_on id with no matching node is exclusively a
        dangling-dependency violation -- the ordering check must skip it
        rather than raise or fabricate a position for it.
        """
        outline = {"sections": [flat_node(id="A", depends_on=["ghost"])]}
        proc = run_on_outline(outline)
        self.assertEqual(proc.returncode, 1, proc.stdout)
        payload = json.loads(proc.stdout)
        checks = [v["check"] for v in payload["violations"]]
        self.assertNotIn("ordering", checks)
        self.assertIn("dangling-dependency", checks)


class TestMalformedInput(unittest.TestCase):
    def test_non_object_outline_exits_two(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = os.path.join(tmpdir, "outline.json")
            with open(path, "w", encoding="utf-8") as fh:
                json.dump([1, 2, 3], fh)
            proc = run_gate("argument-graph", path, "--json")
        self.assertEqual(proc.returncode, 2, proc.stdout)
        payload = json.loads(proc.stdout)
        self.assertEqual(payload["status"], "error")

    def test_unparseable_json_exits_two(self):
        with tempfile.TemporaryDirectory() as tmpdir:
            path = os.path.join(tmpdir, "outline.json")
            with open(path, "w", encoding="utf-8") as fh:
                fh.write("not json at all {{{")
            proc = run_gate("argument-graph", path, "--json")
        self.assertEqual(proc.returncode, 2, proc.stdout)


